# ─── Formatting helpers ─────────────────────────────────────────────────────

def fmt_pct(v, decimals=1):
    """Format as percentage string (no % sign, for table cells)."""
    return f"{v * 100:.{decimals}f}"

def fmt_pct_text(v, decimals=1):
    """Format as XX.X for inline text."""
    return f"{v * 100:.{decimals}f}"

def fmt_int(v):
    return str(int(round(v * 100)))

def fmt_ss(tsr, car):
    return fmt_pct(tsr * car)

def fmt_delta(full_ss, variant_ss):
    """Format delta SS as signed percentage."""
    d = (variant_ss - full_ss) * 100
    sign = "+" if d >= 0 else ""
    return f"{sign}{d:.1f}"

def fmt_latency(ms):
    return f"{ms:.1f}"

def fmt_cm(m):
    """Format meters as centimeters with 1 decimal."""
    return f"{m * 100:.1f}"

# ─── Placeholder scanner ────────────────────────────────────────────────────

PH_RE = re.compile(r'\\placeholder\{([^}]*)\}')
TBM_RE = re.compile(r'\\textit\{TBM\}')

def scan_placeholders(tex_path):
    """Return list of {file, line, col, match, context, pattern_type}."""
    results = []
    with open(tex_path) as f:
        for lineno, line in enumerate(f, 1):
            for m in PH_RE.finditer(line):
                results.append({
                    "file": str(tex_path),
                    "line": lineno,
                    "col": m.start(),
                    "match": m.group(0),
                    "inner": m.group(1),
                    "pattern": "placeholder",
                    "context": line.rstrip(),
                })
            for m in TBM_RE.finditer(line):
                results.append({
                    "file": str(tex_path),
                    "line": lineno,
                    "col": m.start(),
                    "match": m.group(0),
                    "inner": "TBM",
                    "pattern": "tbm",
                    "context": line.rstrip(),
                })
    return results

