def load_safelibero_results(eval_dir, method_dirs=None):
    """Load SafeLIBERO batch eval results.

    Expected structure:
        eval_dir/
            geosafe_*/safelibero_results_{step}_level{level}.json
            baseline_*/safelibero_results_{step}_level{level}.json

    Returns: {method: {suite: {task: {tsr, car, ss}, avg_tsr, avg_car, avg_ss}}}
    """
    if not eval_dir or not Path(eval_dir).exists():
        return {}

    results = {}
    eval_path = Path(eval_dir)

    # Auto-detect method directories
    if method_dirs is None:
        method_dirs = {}
        for d in eval_path.iterdir():
            if d.is_dir():
                name = d.name.lower()
                if "geosafe" in name or "ours" in name:
                    method_dirs["ours"] = d
                elif "baseline" in name or "vanilla" in name:
                    method_dirs["vanilla"] = d
                elif "aegis" in name or "vlsa" in name:
                    method_dirs["aegis"] = d

    for method, mdir in method_dirs.items():
        mdir = Path(mdir)
        # Find the latest result JSON (prefer level I)
        json_files = sorted(mdir.glob("safelibero_results_*_level*.json"))
        if not json_files:
            continue

        # Prefer level I, then latest step
        best = None
        for jf in json_files:
            m = re.search(r'safelibero_results_(\d+)_level(\w+)\.json', jf.name)
            if m:
                step, level = int(m.group(1)), m.group(2)
                if best is None or (level == "I" and best[1] != "I") or step > best[0]:
                    best = (step, level, jf)

        if best is None:
            continue

        with open(best[2]) as f:
            data = json.load(f)

        method_results = {}
        suites_data = data.get("suites", {})
        all_tsr, all_car, all_ss = [], [], []

        for suite in SUITES:
            sd = suites_data.get(suite, {})
            if "error" in sd:
                continue
            suite_res = {
                "avg_tsr": sd.get("avg_tsr", 0),
                "avg_car": sd.get("avg_car", 0),
                "avg_ss": sd.get("avg_ss", 0),
                "tasks": {},
            }
            for tk, tv in sd.get("tasks", {}).items():
                suite_res["tasks"][tk] = {
                    "tsr": tv.get("tsr", 0),
                    "car": tv.get("car", 0),
                    "ss": tv.get("ss", 0),
                }
            all_tsr.append(suite_res["avg_tsr"])
            all_car.append(suite_res["avg_car"])
            all_ss.append(suite_res["avg_ss"])
            method_results[suite] = suite_res

        if all_tsr:
            method_results["overall"] = {
                "avg_tsr": sum(all_tsr) / len(all_tsr),
                "avg_car": sum(all_car) / len(all_car),
                "avg_ss": sum(all_ss) / len(all_ss),
            }
        results[method] = method_results

    return results

def load_learning_curve(lc_path):
    """Load learning curve results.

    Accepts:
      - Directory with step_*_results.json files
      - Single JSON file
      - CSV file (learning_curve_summary.csv)

    Returns: {method: {"libero_spatial": {"avg_tsr": x, "tasks": {task_i: tsr}}}}
    """
    if not lc_path or not Path(lc_path).exists():
        return {}

    lc_path = Path(lc_path)
    results = {}

    if lc_path.is_dir():
        # Look for step JSONs — use the latest step
        json_files = sorted(lc_path.glob("step_*_results.json"))
        if json_files:
            latest = json_files[-1]
            with open(latest) as f:
                data = json.load(f)
            results["_raw"] = {
                "libero_spatial": {
                    "avg_tsr": data.get("avg_tsr", 0),
                    "tasks": data.get("tasks", {}),
                }
            }
    elif lc_path.suffix == ".json":
        with open(lc_path) as f:
            data = json.load(f)
        results["_raw"] = {
            "libero_spatial": {
                "avg_tsr": data.get("avg_tsr", 0),
                "tasks": data.get("tasks", {}),
            }
        }
    elif lc_path.suffix == ".csv":
        import csv
        with open(lc_path) as f:
            reader = csv.DictReader(f)
            rows = list(reader)
        if rows:
            last = rows[-1]
            tasks = {}
            for k, v in last.items():
                m = re.match(r'task_(\d+)_tsr', k)
                if m and v != "NA":
                    tasks[f"task_{m.group(1)}"] = float(v)
            results["_raw"] = {
                "libero_spatial": {
                    "avg_tsr": float(last.get("avg_tsr", 0)),
                    "tasks": tasks,
                }
            }

    return results

