# ─── Value resolver ──────────────────────────────────────────────────────────

class DataStore:
    """Central data store that resolves metric keys to formatted values."""

    def __init__(self, eval_dir=None, lc_ours=None, lc_vanilla=None,
                 latency_files=None, bootstrap_ci=None, ablation_dir=None,
                 sensitivity_dir=None):
        self.safelibero = {}
        self.learning_curve = {}
        self.latency = {}
        self.bootstrap = {}
        self.ablation = {}
        self.sensitivity = {}
        self._loaded_sources = []

        if eval_dir:
            self.safelibero = load_safelibero_results(eval_dir)
            if self.safelibero:
                self._loaded_sources.append(f"safelibero ({len(self.safelibero)} methods)")

        if lc_ours:
            lc = load_learning_curve(lc_ours)
            if lc:
                self.learning_curve["ours"] = lc.get("_raw", {})
                self._loaded_sources.append("learning_curve/ours")

        if lc_vanilla:
            lc = load_learning_curve(lc_vanilla)
            if lc:
                self.learning_curve["vanilla"] = lc.get("_raw", {})
                self._loaded_sources.append("learning_curve/vanilla")

        if latency_files:
            for lf in latency_files:
                data = load_latency(lf)
                if data:
                    mode = data.get("mode", "unknown")
                    self.latency[mode] = data
                    self._loaded_sources.append(f"latency/{mode}")

        if bootstrap_ci:
            self.bootstrap = load_bootstrap_ci(bootstrap_ci)
            if self.bootstrap:
                self._loaded_sources.append("bootstrap_ci")

    def resolve(self, key):
        """Resolve a metric key tuple to a numeric value. Returns None if unavailable."""
        source, method, suite, task, metric = key

        if source == "safelibero":
            method_data = self.safelibero.get(method, {})
            if suite == "overall":
                overall = method_data.get("overall", {})
                return overall.get(metric)
            suite_data = method_data.get(suite, {})
            if task is None:
                return suite_data.get(metric)
            task_data = suite_data.get("tasks", {}).get(task, {})
            return task_data.get(metric)

        elif source == "learning_curve":
            method_data = self.learning_curve.get(method, {})
            suite_data = method_data.get(suite, {})
            if task is None:
                return suite_data.get(metric)
            return suite_data.get("tasks", {}).get(task)

        elif source == "ablation":
            variant_data = self.ablation.get(method, {})
            return variant_data.get(metric)

        elif source == "sensitivity":
            param_data = self.sensitivity.get(method, {})
            return param_data.get(metric)

        elif source == "derived":
            return self._resolve_derived(method)

        elif source == "latency":
            return self._resolve_latency(method)

        elif source == "training":
            return self._resolve_training(method)

        return None

    def _resolve_derived(self, key):
        ours = self.safelibero.get("ours", {}).get("overall", {})
        vanilla = self.safelibero.get("vanilla", {}).get("overall", {})
        if key == "collision_reduction_pct":
            ours_car = ours.get("avg_car")
            vanilla_car = vanilla.get("avg_car")
            if ours_car is not None and vanilla_car is not None and vanilla_car > 0:
                collision_rate_ours = 1 - ours_car
                collision_rate_vanilla = 1 - vanilla_car
                if collision_rate_vanilla > 0:
                    return (collision_rate_vanilla - collision_rate_ours) / collision_rate_vanilla
            return None
        elif key == "tsr_degradation_pp":
            ours_tsr = ours.get("avg_tsr")
            vanilla_tsr = vanilla.get("avg_tsr")
            if ours_tsr is not None and vanilla_tsr is not None:
                return vanilla_tsr - ours_tsr
            return None
        return None

    def _resolve_latency(self, key):
        if "standard" in self.latency:
            stats = self.latency["standard"].get("latency_ms", {})
            if key == "vanilla_ms" or key == "ours_standard_ms":
                return stats.get("mean")
        if "verification" in self.latency:
            stats = self.latency["verification"].get("latency_ms", {})
            if key == "ours_verification_ms":
                return stats.get("mean")
        return None

    def _resolve_training(self, key):
        return None

    def format_value(self, key, value):
        """Format a resolved value for LaTeX insertion."""
        if value is None:
            return None

        source, method, suite, task, metric = key

        if source == "derived":
            if method == "collision_reduction_pct":
                return fmt_int(value)
            elif method == "tsr_degradation_pp":
                return f"{value * 100:.1f}"
            return str(value)

        if source == "latency":
            return fmt_latency(value)

        if source == "training":
            return fmt_cm(value)

        if metric in ("tsr", "car", "ss", "avg_tsr", "avg_car", "avg_ss"):
            return fmt_pct(value)

        if metric == "delta_ss":
            return fmt_delta(0, value)  # pre-computed

        return f"{value:.2f}"

    @property
    def summary(self):
        if not self._loaded_sources:
            return "No data loaded"
        return f"Loaded: {', '.join(self._loaded_sources)}"

# ─── Placeholder mapping engine ──────────────────────────────────────────────

def map_placeholders_to_keys(placeholders, table_mappings, inline_mappings, tbm_mappings):
    """Match each placeholder to its metric key based on file/line position."""
    mapped = []

    for ph in placeholders:
        fname = Path(ph["file"]).name
        line = ph["line"]
        key = None
        table_name = None

        # Check table mappings
        file_tables = table_mappings.get(fname, {})
        if line in file_tables:
            cols = file_tables[line]
            # Count which placeholder on this line (by column position)
            same_line = [p for p in placeholders
                         if p["file"] == ph["file"] and p["line"] == line
                         and p["pattern"] == ph["pattern"]]
            same_line.sort(key=lambda x: x["col"])
            idx = next((i for i, p in enumerate(same_line) if p["col"] == ph["col"]), 0)
            if idx < len(cols):
                key = cols[idx]
                table_name = f"table@{fname}:{line}"

        # Check inline mappings
        if key is None:
            file_inline = inline_mappings.get(fname, {})
            if line in file_inline:
                keys = file_inline[line]
                same_line = [p for p in placeholders
                             if p["file"] == ph["file"] and p["line"] == line
                             and p["pattern"] == ph["pattern"]]
                same_line.sort(key=lambda x: x["col"])
                idx = next((i for i, p in enumerate(same_line) if p["col"] == ph["col"]), 0)
                if idx < len(keys):
                    key = keys[idx]
                    table_name = f"inline@{fname}:{line}"

        # Check TBM mappings
        if key is None and ph["pattern"] == "tbm":
            file_tbm = tbm_mappings.get(fname, {})
            if line in file_tbm:
                keys = file_tbm[line]
                same_line = [p for p in placeholders
                             if p["file"] == ph["file"] and p["line"] == line
                             and p["pattern"] == "tbm"]
                same_line.sort(key=lambda x: x["col"])
                idx = next((i for i, p in enumerate(same_line) if p["col"] == ph["col"]), 0)
                if idx < len(keys):
                    key = keys[idx]
                    table_name = f"tbm@{fname}:{line}"

        mapped.append({
            **ph,
            "key": key,
            "table": table_name,
        })

    return mapped

