def mode_dryrun(mapped, store):
    """Print mapping table with status."""
    print(f"\n{'='*90}")
    print(f"{'File':20s} {'Line':>5s}  {'Placeholder':20s}  {'Key':40s}  {'Value':>10s}  {'Status':8s}")
    print(f"{'='*90}")

    total = len(mapped)
    auto_mapped = sum(1 for m in mapped if m["key"] is not None)
    filled = 0
    missing_data = 0

    for m in mapped:
        fname = Path(m["file"]).name
        if m["key"] is None:
            status = "UNMAPPED"
            value_str = "---"
        else:
            value = store.resolve(m["key"])
            if value is not None:
                formatted = store.format_value(m["key"], value)
                value_str = formatted if formatted else "---"
                status = "FILLED"
                filled += 1
            else:
                value_str = "---"
                status = "NO_DATA"
                missing_data += 1

        key_str = str(m["key"][:3]) if m["key"] else "---"
        print(f"{fname:20s} {m['line']:>5d}  {m['match']:20s}  {key_str:40s}  {value_str:>10s}  {status:8s}")

    print(f"\n{'─'*60}")
    print(f"Total: {total} | Mapped: {auto_mapped} | Filled: {filled} | "
          f"No data: {missing_data} | Unmapped: {total - auto_mapped}")
    print(f"Data: {store.summary}")

def mode_checklist(mapped, store):
    """Output markdown checklist."""
    print("## Placeholder Fill Checklist\n")
    print(f"Generated: {__import__('datetime').datetime.now().strftime('%Y-%m-%d %H:%M')}\n")
    print(f"Data sources: {store.summary}\n")

    total = len(mapped)
    auto_mapped = sum(1 for m in mapped if m["key"] is not None)
    filled = sum(1 for m in mapped if m["key"] and store.resolve(m["key"]) is not None)

    print(f"**Summary**: {total} placeholders | {auto_mapped} auto-mapped | "
          f"{filled} have data | {total - auto_mapped} need manual mapping\n")

    # Group by file and table
    by_file = OrderedDict()
    for m in mapped:
        fname = Path(m["file"]).name
        by_file.setdefault(fname, []).append(m)

    for fname, items in by_file.items():
        print(f"\n### {fname}\n")

        # Group by table/section
        current_table = None
        for m in items:
            table = m.get("table", "")
            if table != current_table:
                current_table = table
                if table:
                    print(f"\n**{table}**\n")
                else:
                    print(f"\n**Unmapped (line {m['line']})**\n")

            if m["key"] is None:
                status = "[ ]"
                note = f"UNMAPPED — context: `{m['context'][:60]}...`"
            else:
                value = store.resolve(m["key"])
                if value is not None:
                    formatted = store.format_value(m["key"], value)
                    status = "[x]"
                    note = f"→ `{formatted}` (from {m['key'][0]})"
                else:
                    status = "[ ]"
                    note = f"key={m['key'][:3]}, waiting for data"

            key_short = f"{m['key'][1]}/{m['key'][2]}" if m["key"] else "?"
            print(f"- {status} L{m['line']}: `{m['match']}` — {key_short} — {note}")

def mode_apply(mapped, store, tex_dir, backup_dir):
    """Replace placeholders in .tex files."""
    backup_path = Path(backup_dir)
    backup_path.mkdir(parents=True, exist_ok=True)

    # Group by file
    by_file = {}
    for m in mapped:
        by_file.setdefault(m["file"], []).append(m)

    replaced_count = 0
    for fpath, items in by_file.items():
        # Backup
        fname = Path(fpath).name
        backup_file = backup_path / f"{fname}.bak"
        shutil.copy2(fpath, backup_file)
        print(f"Backed up: {fpath} → {backup_file}")

        with open(fpath) as f:
            lines = f.readlines()

        # Process each line (reverse order of col to avoid offset issues)
        changes = {}
        for m in items:
            if m["key"] is None:
                continue
            value = store.resolve(m["key"])
            if value is None:
                continue
            formatted = store.format_value(m["key"], value)
            if formatted is None:
                continue

            line_idx = m["line"] - 1
            changes.setdefault(line_idx, []).append({
                "col": m["col"],
                "old": m["match"],
                "new": formatted,
                "pattern": m["pattern"],
            })

        for line_idx, line_changes in changes.items():
            line = lines[line_idx]
            # Sort by col descending to replace from right to left
            for ch in sorted(line_changes, key=lambda x: x["col"], reverse=True):
                old_text = ch["old"]
                new_text = ch["new"]
                pos = line.find(old_text, ch["col"] - 2)  # slight tolerance
                if pos >= 0:
                    line = line[:pos] + new_text + line[pos + len(old_text):]
                    replaced_count += 1
            lines[line_idx] = line

        with open(fpath, "w") as f:
            f.writelines(lines)
        print(f"Updated: {fpath}")

    print(f"\nReplaced {replaced_count} placeholders")

    # Show diff
    for fpath in by_file:
        fname = Path(fpath).name
        backup_file = backup_path / f"{fname}.bak"
        print(f"\n--- diff {fname} ---")
        try:
            result = subprocess.run(
                ["diff", "-u", str(backup_file), fpath],
                capture_output=True, text=True)
            if result.stdout:
                print(result.stdout[:3000])
            else:
                print("(no changes)")
        except Exception:
            print("(diff not available)")

