def main():
    args = parse_args()
    tex_dir = Path(args.tex_dir)

    main_tex = tex_dir / "main.tex"
    appendix_tex = tex_dir / "appendix.tex"

    if not main_tex.exists():
        print(f"ERROR: {main_tex} not found", file=sys.stderr)
        sys.exit(1)
    if not appendix_tex.exists():
        print(f"ERROR: {appendix_tex} not found", file=sys.stderr)
